#!/usr/bin/env python3

"""Test edge cases for the new Greek templates."""

from wikidict.utils import process_templates

def test_edge_cases():
    print("Testing edge cases:")

    # Test ετικ with different parameters
    test_cases = [
        ('{{ετικ|μτφρ}}', 'el'),
        ('{{ετικ|ιατρική}}', 'el'), 
        ('{{ετικ|0=-|ιατρική}}', 'el'),  # Without parentheses
    ]

    for template, locale in test_cases:
        try:
            result = process_templates('test', template, locale)
            print(f"{template} -> {repr(result)}")
        except Exception as e:
            print(f"{template} -> ERROR: {e}")

    print("\nTesting γρ template with different parameters:")

    # Test γρ with different parameters
    test_cases = [
        ('{{γρ|αμερ}}', 'el'),
        ('{{γρ|βρετ}}', 'el'),
        ('{{γρ|0=-|αμερ}}', 'el'),  # Without parentheses
    ]

    for template, locale in test_cases:
        try:
            result = process_templates('test', template, locale)
            print(f"{template} -> {repr(result)}")
        except Exception as e:
            print(f"{template} -> ERROR: {e}")

    print("\nTesting γρ with unknown prefix:")

    # Test γρ with unknown prefix (should handle gracefully)
    test_cases = [
        ('{{γρ|unknown}}', 'el'),
    ]

    for template, locale in test_cases:
        try:
            result = process_templates('test', template, locale)
            print(f"{template} -> {repr(result)}")
        except Exception as e:
            print(f"{template} -> ERROR: {e}")

if __name__ == "__main__":
    test_edge_cases()

